/**
 * @file A deploy's secrets (docs/stratus.adoc, D16): generated by the first
 * deploy and kept beside the VM's record on the host (`auth/chris.json`,
 * mode 600), reused by every replay and rebuild, so a rebuilt VM opens the
 * old database. The admin password is the operator's (asked once, or given
 * by a file) or generated and shown once.
 *
 * @module
 */
import { randomBytes } from 'crypto';
import * as fs from 'fs';
import * as path from 'path';
import type { VmStore } from '../vm/state.js';
import type { ChrisSecrets } from './compose.js';

/**
 * A secret: 32 random bytes, URL-safe.
 *
 * @returns The secret.
 */
export function secret_make(): string {
  return randomBytes(32).toString('base64url');
}

/**
 * Where a VM's deploy keeps its secrets.
 *
 * @param store - The VMs.
 * @param name - The VM.
 * @returns The file.
 */
function secretsFile_derive(store: VmStore, name: string): string {
  return path.join(store.folder_derive(name), 'auth', 'chris.json');
}

/**
 * The secrets kept for a VM's deploy.
 *
 * @param store - The VMs.
 * @param name - The VM.
 * @returns The secrets, or null when none are kept.
 */
export function secrets_read(store: VmStore, name: string): ChrisSecrets | null {
  const file: string = secretsFile_derive(store, name);
  return fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, 'utf-8')) as ChrisSecrets : null;
}

/**
 * The secrets for a deploy: those kept, or new ones with the admin password given, kept.
 *
 * @param store - The VMs.
 * @param name - The VM.
 * @param adminPassword - The admin password for a first deploy.
 * @returns The secrets.
 */
export function secrets_ensure(store: VmStore, name: string, adminPassword: string): ChrisSecrets {
  const kept: ChrisSecrets | null = secrets_read(store, name);
  if (kept !== null) return kept;
  const secrets: ChrisSecrets = { djangoKey: secret_make(), postgresPassword: secret_make(), pfconSecretKey: secret_make(), pfconPassword: secret_make(), adminPassword };
  const file: string = secretsFile_derive(store, name);
  fs.mkdirSync(path.dirname(file), { recursive: true, mode: 0o700 });
  fs.writeFileSync(file, `${JSON.stringify(secrets, null, 2)}\n`, { mode: 0o600 });
  return secrets;
}
